"""
rq_0_cache/shared_utils.py
==========================

Self-contained replacement for what used to be
`alternatives/shared/utils.py`. All 8 stages of the framework now import
from HERE instead of routing through the (legacy) `alternatives/` tree.

Exports
-------
    setup_logging(level)
    discover_ontologies(ontologies_dir, max_file_size_mb=0)
    load_ground_truth(onto_dir)
    aggregate_dual_metrics(tag, evals)
    save_detailed_evaluation(output_dir, approach, primary_evals, ablation_results)
    match_and_evaluate(clusters, gt_patterns, f1_threshold=0.5)

Assumed ontology-dataset layout (adjust `_find_main_ontology_file` and
`load_ground_truth` if yours differs):

    <ontologies_dir>/
        <ontology_A>/
            <ontology_A>.owl            # the main ontology  (any ext: owl/ttl/rdf/xml/nt)
            gt_patterns.json            # (preferred) JSON manifest: {pattern: [iri, ...]}
            patterns/                   # (alternative) one .ttl per pattern
                P1.ttl
                P2.ttl
        <ontology_B>/ ...

Alternatively, flat: `<ontologies_dir>/<onto>.owl` with a sibling
`<onto>.json` or `<onto>.patterns.json` carrying the GT.

Nothing outside `rq_0_cache/` is imported -- this module is the ONLY
canonical source of these helpers from now on.
"""
from __future__ import annotations

import csv
import json
import logging
import os
import re
from pathlib import Path

_ONTO_EXTS = (".owl", ".ttl", ".rdf", ".xml", ".nt")

log = logging.getLogger(__name__)

# labels too generic to be evidence of pattern reuse (would over-match)
_GENERIC_LABELS = {"thing", "entity", "nothing", "class", "concept", ""}


def _norm_label(s: str) -> str:
    s = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(s))   # CamelCase -> spaces
    return re.sub(r"[^a-z0-9]", "", s.lower())            # keep alnum, lowercase


# ======================================================================
# logging
# ======================================================================

def setup_logging(level: str = "INFO") -> None:
    """Configure root logger with a sensible format."""
    lvl = getattr(logging, str(level).upper(), logging.INFO)
    logging.basicConfig(
        level=lvl,
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
    )
    # Tame overly chatty libraries
    for noisy in ("rdflib", "rdflib.plugins.parsers",
                   "urllib3", "matplotlib"):
        logging.getLogger(noisy).setLevel(logging.WARNING)


# ======================================================================
# Ontology discovery -- "what is there on disk to embed"
# ======================================================================

def _find_main_ontology_file(onto_dir: Path) -> Path | None:
    """Inside a single ontology directory, pick the canonical OWL file.

    Priority:
      1. <dirname>.<ext> for any supported ext
      2. "ontology.<ext>"
      3. largest OWL-family file at top-level of the dir (skipping
         obvious pattern files: anything inside a 'patterns' subdir)
    """
    name = onto_dir.name
    # Priority 1 + 2
    for base in (name, "ontology", name.lower()):
        for ext in _ONTO_EXTS:
            p = onto_dir / f"{base}{ext}"
            if p.is_file():
                return p
    # Priority 3: largest top-level OWL file
    candidates = [p for p in onto_dir.iterdir()
                   if p.is_file() and p.suffix.lower() in _ONTO_EXTS]
    if not candidates:
        return None
    candidates.sort(key=lambda p: p.stat().st_size, reverse=True)
    return candidates[0]


def discover_ontologies(ontologies_dir: Path | str,
                           max_file_size_mb: float = 0) -> list[tuple[Path, str]]:
    """Return [(path_to_main_owl, ontology_name), ...] for every ontology
    found under `ontologies_dir`.

    Supports two layouts:
      (a) one subdirectory per ontology (preferred; each dir holds its
          own OWL + GT patterns)
      (b) flat layout: `<ontologies_dir>/<onto>.owl`

    If `max_file_size_mb > 0`, main OWL files exceeding this limit are
    skipped (keeps huge biomedical OWLs out of memory).
    """
    root = Path(ontologies_dir)
    if not root.exists() or not root.is_dir():
        log.warning("discover_ontologies: %s does not exist or is not a dir",
                     root)
        return []

    max_bytes = int(max_file_size_mb * 1024 * 1024) if max_file_size_mb > 0 else None

    results: list[tuple[Path, str]] = []
    subdirs = sorted(p for p in root.iterdir() if p.is_dir())

    if subdirs:
        # Layout (a): one directory per ontology
        for d in subdirs:
            main = _find_main_ontology_file(d)
            if main is None:
                continue
            try:
                size = main.stat().st_size
            except OSError:
                continue
            if max_bytes is not None and size > max_bytes:
                log.debug("skip %s (%.1f MB > %.1f MB limit)",
                           main, size / (1024 * 1024),
                           max_bytes / (1024 * 1024))
                continue
            results.append((main, d.name))
    else:
        # Layout (b): flat files
        for p in sorted(root.iterdir()):
            if not (p.is_file() and p.suffix.lower() in _ONTO_EXTS):
                continue
            try:
                size = p.stat().st_size
            except OSError:
                continue
            if max_bytes is not None and size > max_bytes:
                continue
            results.append((p, p.stem))
    log.info("discover_ontologies(%s): %d ontologies", root, len(results))
    return results


# ======================================================================
# Ground-truth loading -- pattern name -> set of IRIs
# ======================================================================

def _load_gt_from_json(path: Path) -> dict[str, set[str]] | None:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception as e:
        log.warning("gt JSON parse failed %s: %s", path, e)
        return None
    if not isinstance(data, dict):
        return None
    out: dict[str, set[str]] = {}
    for pname, iris in data.items():
        if isinstance(iris, (list, tuple, set)):
            out[str(pname)] = {str(x) for x in iris}
        elif isinstance(iris, dict) and "iris" in iris:
            out[str(pname)] = {str(x) for x in iris["iris"]}
    return out


def _load_gt_from_ttl_dir(pattern_files: list[Path]) -> dict[str, set[str]]:
    """Each .ttl file = one pattern; its IRIs = the set."""
    try:
        from rdflib import Graph, URIRef
    except ImportError:
        log.warning("rdflib missing; cannot load TTL-based GT")
        return {}
    out: dict[str, set[str]] = {}
    for p in sorted(pattern_files):
        try:
            g = Graph()
            g.parse(str(p))
        except Exception as e:
            log.warning("gt TTL parse failed %s: %s", p, e)
            continue
        iris = {str(s) for s in g.subjects() if isinstance(s, URIRef)}
        iris.update(str(o) for o in g.objects() if isinstance(o, URIRef))
        iris.discard("http://www.w3.org/2002/07/owl#Ontology")
        if iris:
            out[p.stem] = iris
    return out


def _load_gt_from_namespaces(pattern_files: list[Path],
                                entity_allowlist: set[str]) -> dict[str, set[str]]:
    """Namespace-based GT loader.

    For each pattern file, read its declared owl:Ontology IRI (the pattern's
    "namespace"), then collect every entity in `entity_allowlist` whose IRI
    starts with that namespace (i.e. belongs to the pattern's URI space).

    The bare namespace IRI itself (with or without a trailing '/') is NOT
    counted as an entity -- only IRIs that extend it with '#localname' or
    '/localname' are included.

    Pattern names come from each file's stem (e.g. ``musicalobject.owl``
    -> ``musicalobject``).
    """
    try:
        from rdflib import Graph, URIRef
    except ImportError:
        log.warning("rdflib missing; cannot load namespace-based GT")
        return {}

    _RDF_TYPE = URIRef("http://www.w3.org/1999/02/22-rdf-syntax-ns#type")
    _OWL_ONTOLOGY = URIRef("http://www.w3.org/2002/07/owl#Ontology")

    out: dict[str, set[str]] = {}
    for p in sorted(pattern_files):
        try:
            g = Graph()
            g.parse(str(p))
        except Exception as e:
            log.warning("gt pattern parse failed %s: %s", p, e)
            continue

        # Find the pattern's declared ontology IRI (its namespace).
        onto_iri: str | None = None
        for s, _, _ in g.triples((None, _RDF_TYPE, _OWL_ONTOLOGY)):
            onto_iri = str(s)
            break
        if onto_iri is None:
            log.warning("no owl:Ontology declaration in %s; skipping", p)
            continue

        # Normalise: strip an optional trailing '/' so we can match
        # either base+'/' or base+'#' children uniformly.
        base = onto_iri.rstrip("/")
        bare_iris = {base, base + "/"}

        matched: set[str] = set()
        for e in entity_allowlist:
            if e in bare_iris:
                continue
            if e.startswith(base + "#") or e.startswith(base + "/"):
                matched.add(e)

        if matched:
            out[p.stem] = matched
        else:
            log.warning("namespace GT for %s yielded 0 entities "
                          "(namespace=%s)", p.name, onto_iri)
    return out


def _structurally_coherent(graph, iris: set) -> set:
    """Precision guard for label-matched GT: an ODP is a CONNECTED fragment, so its
    reuse should be too. For >=2 matched host entities, keep the largest connected
    component (edges = direct IRI->IRI triples, plus one hop through a restriction/
    anon node, e.g. C subClassOf [r some D]); drop scattered coincidental matches.
    A single match passes through (degenerate for clustering, but not a bloat risk).
    """
    from rdflib import URIRef, BNode
    S = list(iris)
    if len(S) <= 1:
        return set(S)
    Sset = set(S)
    adj = {e: set() for e in S}
    for a in S:
        for _, _, o in graph.triples((URIRef(a), None, None)):
            if isinstance(o, URIRef) and str(o) in Sset and str(o) != a:
                adj[a].add(str(o)); adj[str(o)].add(a)
            elif isinstance(o, BNode):                 # follow one hop (restriction)
                for _, _, o2 in graph.triples((o, None, None)):
                    if isinstance(o2, URIRef) and str(o2) in Sset and str(o2) != a:
                        adj[a].add(str(o2)); adj[str(o2)].add(a)
    seen, best = set(), set()
    for start in S:
        if start in seen:
            continue
        comp, st = set(), [start]
        while st:
            u = st.pop()
            if u in seen:
                continue
            seen.add(u); comp.add(u); st.extend(adj[u] - seen)
        if len(comp) > len(best):
            best = comp
    return best if len(best) >= 2 else set()


def _load_gt_from_labels(pattern_files: list[Path], graph,
                          entity_allowlist: set[str]) -> dict[str, set[str]]:
    """FIX 2 (reimplementation-style reuse): match each pattern's named classes to
    host entities by normalised label / local-name (NOT IRI).

    Recovers 'ns_divergence' ontologies where the host re-minted a catalogue pattern
    under its own namespace, so IRI/namespace matching finds nothing. Guards against
    over-matching via `_GENERIC_LABELS`; matches across all label languages. A
    structural check (matched entity must also play the pattern's axiom role) is a
    future refinement -- see rq_14_faithfulness/gt_recovery.py.
    """
    try:
        from rdflib import Graph, URIRef, Literal, RDF, RDFS, OWL
    except ImportError:
        return {}

    # host: {normalised label-or-localname -> set(iri)}  over allowed entities only
    host: dict[str, set[str]] = {}
    for iri in entity_allowlist:
        for o in graph.objects(URIRef(iri), RDFS.label):
            if isinstance(o, Literal):
                k = _norm_label(str(o))
                if k not in _GENERIC_LABELS:
                    host.setdefault(k, set()).add(iri)
        k = _norm_label(iri.rsplit("#", 1)[-1].rsplit("/", 1)[-1])
        if k not in _GENERIC_LABELS:
            host.setdefault(k, set()).add(iri)

    out: dict[str, set[str]] = {}
    for p in sorted(pattern_files):
        try:
            pg = Graph(); pg.parse(str(p))
        except Exception as e:  # noqa: BLE001
            log.warning("label-GT: pattern parse failed %s: %s", p.name, e)
            continue
        matched: set[str] = set()
        for c, _, _ in pg.triples((None, RDF.type, OWL.Class)):
            if not isinstance(c, URIRef):
                continue
            keys = {_norm_label(c.rsplit("#", 1)[-1].rsplit("/", 1)[-1])}
            for o in pg.objects(c, RDFS.label):
                if isinstance(o, Literal):
                    keys.add(_norm_label(str(o)))
            for k in keys:
                if k and k not in _GENERIC_LABELS and k in host:
                    matched |= host[k]
        matched = _structurally_coherent(graph, matched)   # precision guard
        if matched:
            out[p.stem] = matched
    return out


def load_ground_truth(onto_dir: Path | str,
                         entity_allowlist: set[str] | None = None,
                         graph=None
                        ) -> dict[str, set[str]]:
    """Load GT patterns for one ontology.

    Tries these layouts in order (first match wins):
      1. <onto_dir>/gt_patterns.json      (preferred: {pattern: [iri,...]})
      2. <onto_dir>/patterns.json
      3. <onto_dir>/ground_truth.json
      4. <onto_dir>/patterns/*.{ttl,owl,rdf,xml}
                                          (one file per pattern)
      5. top-level *.ttl siblings of the main OWL (excluding the main OWL)

    Layout 4 has two backends:
      * If ``entity_allowlist`` is provided, the pattern's declared
        owl:Ontology IRI is used as a namespace prefix to filter
        entities present in the main ontology. This is the reliable path
        and is strongly preferred.
      * If ``entity_allowlist`` is None, we fall back to the legacy
        ``_load_gt_from_ttl_dir`` which simply unions every IRI found in
        each pattern file. That path is unreliable (it includes IRIs that
        the main ontology does not actually contain, and excludes
        same-namespace IRIs defined only in the main ontology) and emits
        a warning.

    Args:
        onto_dir: directory containing one ontology + its patterns.
        entity_allowlist: optional set of entity IRIs present in the main
            ontology (e.g. ``{str(s) for s in g.subjects() if isinstance(s,
            URIRef)}``). Required for namespace-based GT.

    Returns {} if no GT found.
    """
    d = Path(onto_dir)
    if not d.exists():
        return {}

    for name in ("gt_patterns.json", "patterns.json", "ground_truth.json",
                  "gt.json"):
        p = d / name
        if p.exists():
            out = _load_gt_from_json(p)
            if out:
                return out

    patterns_dir = d / "patterns"
    if patterns_dir.exists() and patterns_dir.is_dir():
        files = [p for p in patterns_dir.iterdir()
                  if p.is_file() and p.suffix.lower() in (".ttl", ".rdf",
                                                             ".owl", ".xml")]
        if files:
            if entity_allowlist is not None:
                out = _load_gt_from_namespaces(files, entity_allowlist)
                if out:
                    return out
                # FIX 2: reimplementation-style reuse -- the host re-minted the pattern
                # under its own namespace, so IRI matching finds nothing. Match pattern
                # classes to host entities by label. Opt-in (ODP_LABEL_GT=1); needs the
                # parsed host graph (passed by build_cache).
                if graph is not None and os.environ.get("ODP_LABEL_GT", "0") == "1":
                    out = _load_gt_from_labels(files, graph, entity_allowlist)
                    if out:
                        log.info("label-GT recovered %d pattern(s) for %s", len(out), d.name)
                        return out
            else:
                log.warning(
                    "load_ground_truth(%s): no entity_allowlist supplied; "
                    "falling back to legacy _load_gt_from_ttl_dir, which is "
                    "unreliable -- pass entity_allowlist=<main-ontology "
                    "entities> to get namespace-filtered GT.", d)
                out = _load_gt_from_ttl_dir(files)
                if out:
                    return out

    main = _find_main_ontology_file(d)
    sibling_ttls = [p for p in d.iterdir()
                     if p.is_file() and p.suffix.lower() == ".ttl"
                     and (main is None or p != main)]
    if sibling_ttls:
        out = _load_gt_from_ttl_dir(sibling_ttls)
        if out:
            return out

    return {}


# ======================================================================
# Hungarian cluster-to-pattern matching (basic)
# ======================================================================

def match_and_evaluate(clusters: dict, gt_patterns: dict,
                         f1_threshold: float = 0.5) -> dict:
    """Hungarian matching + standard metrics.

    Args:
        clusters:     {cluster_id: set[str]}  predicted entity groups
        gt_patterns:  {pattern_name: set[str]}  ground-truth entity groups
        f1_threshold: instance-level match threshold

    Returns dict with:
        macro/micro/instance precision/recall/F1 fields,
        total_tp, total_fp, total_fn,
        n_predicted, n_ground_truth, n_matched
    """
    from scipy.optimize import linear_sum_assignment
    import numpy as np

    cids = list(clusters.keys())
    gts = list(gt_patterns.keys())
    nC = len(cids)
    nG = len(gts)
    if nC == 0 or nG == 0:
        zero = {k: 0.0 for k in (
            "macro_entity_precision", "macro_entity_recall", "macro_entity_f1",
            "micro_entity_precision", "micro_entity_recall", "micro_entity_f1",
            "instance_precision", "instance_recall", "instance_f1")}
        zero.update({"total_tp": 0, "total_fp": 0, "total_fn": 0,
                     "n_predicted": nC, "n_ground_truth": nG, "n_matched": 0})
        return zero

    cost = np.ones((nG, nC), dtype=np.float64)
    pair_stats: dict[tuple[int, int], tuple[int, int, int, float, float, float]] = {}
    for i, g in enumerate(gts):
        g_set = gt_patterns[g]
        for j, c in enumerate(cids):
            c_set = clusters[c]
            tp = len(g_set & c_set)
            if tp == 0:
                continue
            fp = len(c_set - g_set)
            fn = len(g_set - c_set)
            prec = tp / max(tp + fp, 1)
            rec = tp / max(tp + fn, 1)
            if prec + rec <= 0:
                continue
            f1 = 2 * prec * rec / (prec + rec)
            cost[i, j] = 1.0 - f1
            pair_stats[(i, j)] = (tp, fp, fn, prec, rec, f1)

    row_ind, col_ind = linear_sum_assignment(cost)
    total_tp = total_fp = total_fn = 0
    per_pattern_prf = []
    n_matched = 0
    for i, j in zip(row_ind, col_ind):
        s = pair_stats.get((i, j))
        if s is None:
            g_set = gt_patterns[gts[i]]
            total_fn += len(g_set)
            per_pattern_prf.append((0.0, 0.0, 0.0))
            continue
        tp, fp, fn, prec, rec, f1 = s
        total_tp += tp
        total_fp += fp
        total_fn += fn
        per_pattern_prf.append((prec, rec, f1))
        if f1 >= f1_threshold:
            n_matched += 1

    macro_p = float(np.mean([p for p, _, _ in per_pattern_prf])) if per_pattern_prf else 0.0
    macro_r = float(np.mean([r for _, r, _ in per_pattern_prf])) if per_pattern_prf else 0.0
    macro_f = float(np.mean([f for _, _, f in per_pattern_prf])) if per_pattern_prf else 0.0
    mp = total_tp / max(total_tp + total_fp, 1)
    mr = total_tp / max(total_tp + total_fn, 1)
    mf = 2 * mp * mr / max(mp + mr, 1e-10) if (mp + mr) else 0.0

    ip = n_matched / max(nC, 1)
    ir = n_matched / max(nG, 1)
    ifs = 2 * ip * ir / max(ip + ir, 1e-10) if (ip + ir) else 0.0

    return {
        "macro_entity_precision": round(macro_p, 4),
        "macro_entity_recall":    round(macro_r, 4),
        "macro_entity_f1":        round(macro_f, 4),
        "micro_entity_precision": round(float(mp), 4),
        "micro_entity_recall":    round(float(mr), 4),
        "micro_entity_f1":        round(float(mf), 4),
        "instance_precision":     round(float(ip), 4),
        "instance_recall":        round(float(ir), 4),
        "instance_f1":            round(float(ifs), 4),
        "total_tp": int(total_tp),
        "total_fp": int(total_fp),
        "total_fn": int(total_fn),
        "n_predicted": nC,
        "n_ground_truth": nG,
        "n_matched": n_matched,
    }


# ======================================================================
# Aggregation -- average the 9 dual metrics across ontologies
# ======================================================================

def aggregate_dual_metrics(tag: str, evals: list[dict]) -> dict:
    """Mean-over-ontologies aggregation for the 9 standard metric fields.

    Returns a summary row keyed by `tag` with `n_ontologies` and one
    `mean_<metric>` entry per metric. Same shape as before so downstream
    code (RQ4, RQ5) continues to work; RQ1 / RQ2 / RQ3 use the richer
    `aggregate_rich_metrics` in `rich_eval.py`.
    """
    import numpy as np
    result = {"tag": tag, "n_ontologies": len(evals)}
    if not evals:
        return result
    for m in ("instance_precision", "instance_recall", "instance_f1",
               "micro_entity_precision", "micro_entity_recall",
               "micro_entity_f1",
               "macro_entity_precision", "macro_entity_recall",
               "macro_entity_f1"):
        vals = [float(e.get(m, 0) or 0) for e in evals]
        result[f"mean_{m}"] = round(float(np.mean(vals)), 4) if vals else 0.0
    return result


# ======================================================================
# Detailed per-ontology + ablation CSV writers
# ======================================================================

def save_detailed_evaluation(output_dir: Path | str, approach: str,
                               primary_evals: list[dict],
                               ablation_results: list[dict]) -> None:
    """Write two CSVs into output_dir:

        evaluation.csv          per-ontology rows for the best config
        detailed_evaluation.csv per (ontology x config) grid + summary_table.csv
                                   (ablation: one row per config)
    """
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    # evaluation.csv -- per-ontology rows for the best config
    if primary_evals:
        cols = [k for k in ("ontology", "mode",
                              "macro_entity_precision", "macro_entity_recall",
                              "macro_entity_f1",
                              "micro_entity_precision", "micro_entity_recall",
                              "micro_entity_f1",
                              "instance_precision", "instance_recall",
                              "instance_f1",
                              "total_tp", "total_fp", "total_fn",
                              "n_predicted", "n_ground_truth", "n_matched",
                              "embedding_dim", "n_entities",
                              "n_gt_patterns", "n_predicted_clusters")
                if any(k in e for e in primary_evals)]
        with open(output_dir / "evaluation.csv", "w", newline="",
                   encoding="utf-8") as f:
            w = csv.DictWriter(f, fieldnames=cols, extrasaction="ignore")
            w.writeheader()
            for ev in primary_evals:
                w.writerow({k: ev.get(k, "") for k in cols})

    # summary_table.csv -- one row per config (ablation results)
    if ablation_results:
        # Normalise keys (rows may vary); union of keys
        keys: list[str] = []
        seen: set[str] = set()
        for r in ablation_results:
            for k in r:
                if k not in seen:
                    seen.add(k); keys.append(k)
        with open(output_dir / "summary_table.csv", "w", newline="",
                   encoding="utf-8") as f:
            w = csv.DictWriter(f, fieldnames=keys, extrasaction="ignore")
            w.writeheader()
            for r in ablation_results:
                w.writerow({k: r.get(k, "") for k in keys})

    # detailed_evaluation.csv -- approach header + linked to above
    with open(output_dir / "detailed_evaluation.csv", "w", newline="",
               encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["approach", approach])
        w.writerow(["n_configs", len(ablation_results)])
        w.writerow(["n_ontologies_primary", len(primary_evals)])
        w.writerow([])
        w.writerow(["see also:", "evaluation.csv", "summary_table.csv"])
